/* QuickSight 923b7881-a4ef-4c39-94fc-bac7a04ec53e */
SELECT "workspaceid" AS "abf7d2f1-72c9-44eb-9d7c-df8df29649e4.workspaceid", "usagedate" AS "abf7d2f1-72c9-44eb-9d7c-df8df29649e4.usagedate", "clustername" AS "abf7d2f1-72c9-44eb-9d7c-df8df29649e4.clustername", "sku" AS "abf7d2f1-72c9-44eb-9d7c-df8df29649e4.sku", "dbus" AS "abf7d2f1-72c9-44eb-9d7c-df8df29649e4.dbus", "mapped_sku" AS "abf7d2f1-72c9-44eb-9d7c-df8df29649e4.mapped_sku", "rate" AS "abf7d2f1-72c9-44eb-9d7c-df8df29649e4.rate"
FROM "PayerAwsDataCatalog"."databricks"."monthly_bill_by_workspace"

/* cppi::bf279a6b3e692393e138969f31406ac968283d35fff97385fddb7648976f3f0c */
select business_date as date_, security_id, 'EUGBR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-16' and business_date <= date '2025-06-16' and weight_ndo>0 and id_cppib_index = 'EUGBR_GR_USD_0_0'

